class Solution:
    def getNumberOfBacklogOrders(self, orders: List[List[int]]) -> int:
        buy, sell = [], []
        for price, amount, typ in orders:
            book = sell if typ == 0 else buy
            while amount:
                best = -1
                for i, pa in enumerate(book):
                    p = pa[0]
                    if typ == 0:
                        if p > price:
                            continue
                        if best < 0 or p < book[best][0]:
                            best = i
                    else:
                        if p < price:
                            continue
                        if best < 0 or p > book[best][0]:
                            best = i
                if best < 0:
                    break
                take = min(amount, book[best][1])
                amount -= take
                book[best][1] -= take
                if book[best][1] == 0:
                    book.pop(best)
            if amount:
                (buy if typ == 0 else sell).append([price, amount])
        return sum(a for _, a in buy + sell) % (10 ** 9 + 7)

