class Solution {
public:
    int getNumberOfBacklogOrders(vector<vector<int>>& orders) {
        vector<array<long long, 2>> buy, sell;
        const long long MOD = 1e9 + 7;
        for (auto& o : orders) {
            long long price = o[0], amount = o[1];
            bool isBuy = o[2] == 0;
            auto& opp = isBuy ? sell : buy;
            while (amount > 0) {
                int best = -1;
                for (int i = 0; i < (int)opp.size(); ++i) {
                    bool ok = isBuy ? opp[i][0] <= price : opp[i][0] >= price;
                    if (!ok) continue;
                    if (best < 0 || (isBuy ? opp[i][0] < opp[best][0] : opp[i][0] > opp[best][0]))
                        best = i;
                }
                if (best < 0) break;
                long long take = min(amount, opp[best][1]);
                amount -= take;
                opp[best][1] -= take;
                if (opp[best][1] == 0) opp.erase(opp.begin() + best);
            }
            if (amount > 0) (isBuy ? buy : sell).push_back({price, amount});
        }
        long long ans = 0;
        for (auto& x : buy) ans += x[1];
        for (auto& x : sell) ans += x[1];
        return (int)(ans % MOD);
    }
};

