class Solution {
public:
    int getNumberOfBacklogOrders(vector<vector<int>>& orders) {
        priority_queue<pair<long long, long long>> buy;
        priority_queue<pair<long long, long long>, vector<pair<long long, long long>>, greater<>> sell;
        const long long MOD = 1e9 + 7;
        for (auto& o : orders) {
            long long price = o[0], amount = o[1];
            if (o[2] == 0) {
                while (amount && !sell.empty() && sell.top().first <= price) {
                    auto [p, a] = sell.top();
                    sell.pop();
                    long long take = min(amount, a);
                    amount -= take;
                    a -= take;
                    if (a) sell.push({p, a});
                }
                if (amount) buy.push({price, amount});
            } else {
                while (amount && !buy.empty() && buy.top().first >= price) {
                    auto [p, a] = buy.top();
                    buy.pop();
                    long long take = min(amount, a);
                    amount -= take;
                    a -= take;
                    if (a) buy.push({p, a});
                }
                if (amount) sell.push({price, amount});
            }
        }
        long long ans = 0;
        while (!buy.empty()) { ans += buy.top().second; buy.pop(); }
        while (!sell.empty()) { ans += sell.top().second; sell.pop(); }
        return (int)(ans % MOD);
    }
};

