class Solution {
    public int getNumberOfBacklogOrders(int[][] orders) {
        PriorityQueue<long[]> buy = new PriorityQueue<>((x, y) -> Long.compare(y[0], x[0]));
        PriorityQueue<long[]> sell = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
        for (int[] o : orders) {
            long price = o[0], amount = o[1];
            if (o[2] == 0) {
                while (amount > 0 && !sell.isEmpty() && sell.peek()[0] <= price) {
                    long[] top = sell.poll();
                    long take = Math.min(amount, top[1]);
                    amount -= take;
                    top[1] -= take;
                    if (top[1] > 0) sell.offer(top);
                }
                if (amount > 0) buy.offer(new long[]{price, amount});
            } else {
                while (amount > 0 && !buy.isEmpty() && buy.peek()[0] >= price) {
                    long[] top = buy.poll();
                    long take = Math.min(amount, top[1]);
                    amount -= take;
                    top[1] -= take;
                    if (top[1] > 0) buy.offer(top);
                }
                if (amount > 0) sell.offer(new long[]{price, amount});
            }
        }
        long ans = 0, MOD = 1_000_000_007L;
        for (long[] x : buy) ans += x[1];
        for (long[] x : sell) ans += x[1];
        return (int) (ans % MOD);
    }
}

