var getNumberOfBacklogOrders = function(orders) {
    const MOD = 1000000007n;
    const mkHeap = (cmp) => ({
        a: [],
        push(v) {
            this.a.push(v);
            let i = this.a.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (cmp(this.a[p], this.a[i]) <= 0) break;
                [this.a[p], this.a[i]] = [this.a[i], this.a[p]];
                i = p;
            }
        },
        pop() {
            const top = this.a[0], last = this.a.pop();
            if (this.a.length) {
                this.a[0] = last;
                let i = 0;
                for (;;) {
                    let m = i;
                    const l = 2 * i + 1, r = l + 1;
                    if (l < this.a.length && cmp(this.a[l], this.a[m]) < 0) m = l;
                    if (r < this.a.length && cmp(this.a[r], this.a[m]) < 0) m = r;
                    if (m === i) break;
                    [this.a[m], this.a[i]] = [this.a[i], this.a[m]];
                    i = m;
                }
            }
            return top;
        },
        peek() { return this.a[0]; },
        get size() { return this.a.length; }
    });
    const buy = mkHeap((x, y) => y[0] - x[0]);
    const sell = mkHeap((x, y) => x[0] - y[0]);
    for (const [price, amount0, typ] of orders) {
        let amount = BigInt(amount0);
        if (typ === 0) {
            while (amount > 0n && sell.size && sell.peek()[0] <= price) {
                const top = sell.pop();
                const take = amount < top[1] ? amount : top[1];
                amount -= take;
                top[1] -= take;
                if (top[1] > 0n) sell.push(top);
            }
            if (amount > 0n) buy.push([BigInt(price), amount]);
        } else {
            while (amount > 0n && buy.size && buy.peek()[0] >= price) {
                const top = buy.pop();
                const take = amount < top[1] ? amount : top[1];
                amount -= take;
                top[1] -= take;
                if (top[1] > 0n) buy.push(top);
            }
            if (amount > 0n) sell.push([BigInt(price), amount]);
        }
    }
    let ans = 0n;
    for (const [, a] of buy.a) ans += a;
    for (const [, a] of sell.a) ans += a;
    return Number(ans % MOD);
};
